    else:cross[1:]=((f[1:]<m[1:])&(f[:-1]>=m[:-1])&~np.isnan(f[1:])&~np.isnan(m[1:])&~np.isnan(f[:-1])&~np.isnan(m[:-1])).astype(np.int8)
